  account: ['CONTA', 'ACCOUNT'], ac_mycats: ['MEUS GATOS', 'MY CATS'], ac_ownTitle: ['Seus gatos oficiais: Mimo, Mimosa e Mortícia', 'Your official cats: Mimo, Mimosa and Morticia'], ac_ownText: ['Conta de dono: os três já são seus, com a Edição dos Mimos (todos os itens, veículos e pinturas liberados). Não precisa criar gato.', 'Owner account: the three are already yours, with the Mimos Edition (every item, vehicle and paint unlocked). No need to create a cat.'], ac_ownPlay: ['Jogar com os Mimos', 'Play as the Mimos'], ac_ownOn: ['Jogando com Mimo, Mimosa e Mortícia 👑', 'Playing as Mimo, Mimosa and Morticia 👑'], ac_otherCats: ['OUTROS GATOS (opcional)', 'OTHER CATS (optional)'], ac_create: ['Crie seu gato', 'Create your cat'], ac_local: ['só neste aparelho', 'this device only'],
  ac_why: ['Entre para salvar seus gatos e o progresso na nuvem. Sem senha: use o Google ou um código de 6 dígitos enviado por e-mail.', 'Sign in to save your cats and progress to the cloud. No password: use Google or a 6-digit code sent by e-mail.'],
  ac_send: ['Enviar código', 'Send code'], ac_sent: ['Enviamos um código para {0}. Vale por 10 minutos.', 'We sent a code to {0}. Valid for 10 minutes.'], ac_enter: ['Entrar', 'Sign in'], ac_other: ['Outro e-mail', 'Other e-mail'],
  ac_note: ['Guardamos só o e-mail, um identificador do Google e o mês/ano de nascimento (criptografado). Sem senha, sem documentos, e nada disso aparece para outros jogadores. Aqui quem tem perfil é o gato.', 'We only keep your e-mail, a Google identifier and your birth month/year (encrypted). No password, no documents, and none of it is shown to other players. Here the cat has the profile, not you.'],
